long handle_dedupe_ioctl(struct file *file, void __user *arg)
{
    struct dedupe_ioctl_data __user *user_data = arg;
    struct dedupe_ioctl_data *kernel_data;
    long dst_count;
    long ret = 0;

    if (get_user(dst_count, &user_data->dst_count))
        return -EFAULT;

    kernel_data = kmalloc(sizeof(*kernel_data), GFP_KERNEL);
    if (!kernel_data)
        return -ENOMEM;

    if (copy_from_user(kernel_data, user_data, sizeof(*kernel_data))) {
        ret = -EFAULT;
        goto out_free;
    }

    ret = perform_dedupe(file, kernel_data);
    if (ret < 0)
        goto out_free;

    if (copy_to_user(user_data, kernel_data, sizeof(*kernel_data)))
        ret = -EFAULT;

out_free:
    kfree(kernel_data);
    return ret;
}

long handle_deduplicate(struct file *file, void __user *arg)
{
    int dest_count;
    struct deduplication_params *params;
    long ret = 0;

    if (copy_from_user(&dest_count, arg, sizeof(dest_count)))
        return -EFAULT;

    params = kmalloc(sizeof(*params), GFP_KERNEL);
    if (!params)
        return -ENOMEM;

    if (copy_from_user(params, arg, sizeof(*params))) {
        kfree(params);
        return -EFAULT;
    }

    ret = perform_deduplication(file, params);
    if (ret < 0) {
        kfree(params);
        return ret;
    }

    if (copy_to_user(arg, params, sizeof(*params))) {
        kfree(params);
        return -EFAULT;
    }

    kfree(params);
    return 0;
}

