long handle_deduplication_ioctl(struct file *file, void __user *arg) {
    long dst_count;
    struct deduplication_params *params;
    struct deduplication_result result;
    long ret;

    if (copy_from_user(&dst_count, arg, sizeof(long)))
        return -EFAULT;

    params = kmalloc(sizeof(*params), GFP_KERNEL);
    if (!params)
        return -ENOMEM;

    if (copy_from_user(params, arg, sizeof(*params))) {
        kfree(params);
        return -EFAULT;
    }

    ret = perform_deduplication(file, params, &result);
    if (ret < 0) {
        kfree(params);
        return ret;
    }

    if (copy_to_user(arg, &result, sizeof(result))) {
        kfree(params);
        return -EFAULT;
    }

    kfree(params);
    return 0;
}
